#!/usr/bin/env bash
# Independent re-run of every Tier 1 model over all 12,110 images, written to a SHADOW
# directory so the committed outputs are untouched and the two can be compared.
#
# Uses only the GPUs named in GPUS (default "1 2"), because this machine is shared and
# other people's training jobs must not be starved of memory.
#
#   setsid nohup bash scripts/signal_rebuild/run_full_tier1_rerun_shadow.sh \
#       < /dev/null > /dev/null 2>&1 & disown
#
# Do NOT edit this file while it is running. Bash reads a script incrementally by byte
# offset, so an edit made during a long `wait` corrupts what it reads next. That is how
# the first shadow run died between the LLaVA and Kosmos stages.
set -u
BASE=/data/brhanu/thesis_project
PY=$BASE/.venv/bin/python3
SHADOW=$BASE/results/signal_rebuild_rerun
GPUS="${GPUS:-1 2}"
LOG=$SHADOW/rerun.log
mkdir -p "$SHADOW"
say(){ echo "[$(date -u +%H:%M:%S)] $*" >> "$LOG"; }
read -ra G <<< "$GPUS"; N=${#G[@]}

say "=== SHADOW TIER 1 RE-RUN START on GPUs: $GPUS ($N shards) ==="

say "STAGE 1  YOLOv11 detector"
rm -f "$SHADOW/yolo_full_corpus.jsonl"
# Ultralytics selects by PHYSICAL index and ignores CUDA_VISIBLE_DEVICES, so the real
# GPU number is passed through --device rather than masking the environment.
$PY $BASE/scripts/signal_rebuild/run_yolo_full_corpus.py \
  --device ${G[0]} --batch 48 --out-root "$SHADOW" >> "$SHADOW/yolo.log" 2>&1
say "STAGE 1  done -> $(wc -l < $SHADOW/yolo_full_corpus.jsonl 2>/dev/null || echo 0) rows"

say "STAGE 2  SigLIP scene"
OUT_ROOT="$SHADOW" CUDA_VISIBLE_DEVICES=${G[0]} $PY \
  $BASE/scripts/signal_rebuild/run_siglip_scene_full_corpus.py >> "$SHADOW/siglip.log" 2>&1
say "STAGE 2  done -> $(wc -l < $SHADOW/siglip_scene_full.jsonl 2>/dev/null || echo 0) rows"

say "STAGE 3  LLaVA-OneVision ($N shards)"
for i in $(seq 0 $((N-1))); do
  CUDA_VISIBLE_DEVICES=${G[$i]} nohup $PY $BASE/scripts/signal_rebuild/run_llava_full_corpus.py \
    --shard $i --num-shards $N --out-root "$SHADOW" >> "$SHADOW/llava_$i.log" 2>&1 &
done
wait
say "STAGE 3  done -> $(cat $SHADOW/llava_full/shard_*.jsonl 2>/dev/null | wc -l) rows"

say "STAGE 4  Kosmos-2.5 ($N shards)"
for i in $(seq 0 $((N-1))); do
  CUDA_VISIBLE_DEVICES=${G[$i]} nohup $PY $BASE/scripts/signal_rebuild/run_kosmos_full_corpus.py \
    --shard $i --num-shards $N --out-root "$SHADOW" >> "$SHADOW/kosmos_$i.log" 2>&1 &
done
wait
say "STAGE 4  done -> $(cat $SHADOW/kosmos_full/shard_*.jsonl 2>/dev/null | wc -l) rows"

say "=== ALL STAGES COMPLETE ==="
